<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import { inviteRoles, roles } from '@footlab/shared';
import { useClub } from '../stores/club';
import { api, errorMessage } from '../services/api';
import RecordEditor, { type EditorField } from '../components/RecordEditor.vue';
import StateNotice from '../components/StateNotice.vue';
import MatchCard from '../components/MatchCard.vue';
const club = useClub(); const tab = ref('players'), players = ref<any[]>([]), teams = ref<any[]>([]), matches = ref<any[]>([]), competitions = ref<any[]>([]), seasons = ref<any[]>([]), members = ref<any[]>([]), detail = ref<any>(), invitations = ref<any[]>([]), newInvitation = ref<any>();
const busy = ref(false), error = ref(''), message = ref(''), query = ref('');
const editor = ref<{ title: string; path: string; method: 'post' | 'patch'; fields: EditorField[]; initial?: Record<string, any>; after?: string }>(); const saving = ref(false), editorError = ref('');
const options = (items: any[], key = 'name') => items.map(x => ({ value: x.id, label: x[key] }));
const text = (key: string, label: string, type = 'text', required = true): EditorField => ({ key, label, type, required });
const select = (key: string, label: string, values: { value: string; label: string }[]): EditorField => ({ key, label, options: values, required: true });
async function load() { if (!club.selectedId) return; busy.value = true; error.value = ''; try {
  const responses = await Promise.all(['/players', '/teams', '/matches', '/competitions', '/competitions/seasons', `/organizations/${club.selectedId}/members`].map(path => api.get(path, { params: { ...club.params, ...(['/players', '/teams'].includes(path) ? { q: query.value, limit: 100 } : {}) } })));
  players.value = responses[0]!.data.items; teams.value = responses[1]!.data.items; matches.value = responses[2]!.data.items; competitions.value = responses[3]!.data.items; seasons.value = responses[4]!.data; members.value = responses[5]!.data; invitations.value = club.can('members:write') ? (await api.get(`/organizations/${club.selectedId}/invitations`)).data : [];
  if (detail.value) detail.value = (await api.get(`/teams/${detail.value.id}`, { params: club.params })).data;
} catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load); watch(() => club.selectedId, () => { detail.value = undefined; load(); });
function open(title: string, path: string, fields: EditorField[], initial?: any, method: 'post' | 'patch' = 'post', after?: string) { editorError.value = ''; editor.value = { title, path, fields, initial: initial ?? {}, method, after }; }
function player(p?: any) { open(p ? 'Editar jugador' : 'Nuevo jugador', p ? `/players/${p.id}` : '/players', [text('name', 'Nombre completo'), select('position', 'Posición', ['GK', 'DF', 'MF', 'FW'].map(p => ({ value: p, label: { GK: 'Portero', DF: 'Defensa', MF: 'Centrocampista', FW: 'Delantero' }[p]! }))), text('birthDate', 'Fecha de nacimiento', 'date', false), text('nationality', 'Nacionalidad', 'text', false)], p ? { ...p, birthDate: p.birthDate?.slice(0, 10) } : {}, p ? 'patch' : 'post'); }
function team(t?: any) { open(t ? 'Editar equipo' : 'Nuevo equipo', t ? `/teams/${t.id}` : '/teams', [text('name', 'Nombre del equipo'), text('category', 'Categoría')], t, t ? 'patch' : 'post'); }
function match() { open('Programar partido', '/matches', [select('homeTeamId', 'Local', options(teams.value)), select('awayTeamId', 'Visitante', options(teams.value)), select('seasonId', 'Temporada', options(seasons.value)), text('kickoff', 'Fecha y hora local', 'datetime-local')]); }
function squad() { open('Asignar o actualizar plantilla', '/teams/squads', [select('playerId', 'Jugador', options(players.value)), select('teamId', 'Equipo', options(teams.value)), select('seasonId', 'Temporada', options(seasons.value)), { ...text('shirtNumber', 'Dorsal', 'number', false), min: 1, max: 99 }, text('joinedAt', 'Desde', 'date'), text('leftAt', 'Hasta (opcional)', 'date', false)], detail.value ? { teamId: detail.value.id } : {}); }
async function save(values: Record<string, any>) { if (!editor.value) return; saving.value = true; editorError.value = ''; try {
  if (values.kickoff) values.kickoff = new Date(values.kickoff).toISOString();
  const { data } = await api.request({ url: editor.value.path, method: editor.value.method, data: values, params: editor.value.after === 'org' ? {} : club.params });
  if (editor.value.path.endsWith('/invitations')) newInvitation.value = data;
  if (editor.value.after === 'org') { await club.load(); await club.select(data.id); } else if (editor.value.path.startsWith('/organizations')) await club.load();
  editor.value = undefined; message.value = 'Cambios guardados en tu club.'; await load();
} catch (e) { editorError.value = errorMessage(e); } finally { saving.value = false; } }
async function showTeam(id: string) { try { detail.value = (await api.get(`/teams/${id}`, { params: club.params })).data; } catch (e) { error.value = errorMessage(e); } }
async function archive(type: string, id: string) { try { await api.delete(`/${type}/${id}`, { params: club.params }); message.value = 'Registro archivado. Su historial se conserva.'; await load(); } catch (e) { error.value = errorMessage(e); } }
async function removeStaff(id: string) { try { await api.delete(`/teams/staff/${id}`, { params: club.params }); await load(); } catch (e) { error.value = errorMessage(e); } }
async function removeMember(userId: string) { try { await api.delete(`/organizations/${club.selectedId}/members/${userId}`); await club.load(); await load(); } catch (e) { error.value = errorMessage(e); } }
async function revokeInvitation(id: string) { try { await api.delete(`/organizations/${club.selectedId}/invitations/${id}`); if (newInvitation.value?.id === id) newInvitation.value = undefined; await load(); } catch (e) { error.value = errorMessage(e); } }
function invite() { open('Invitar a mi equipo', `/organizations/${club.selectedId}/invitations`, [text('email', 'Correo de la persona invitada', 'email'), select('role', 'Permisos en este club', inviteRoles.map(r => ({ value: r, label: r })))]); }
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">FOOTLAB CLUB</span><h1>Tu equipo. <span class="accent">Tu proyecto.</span></h1><p>{{ club.selected?.organization.name ?? 'Crea una organización para empezar a trabajar.' }}</p></div><button class="button subtle" @click="open('Crear club', '/organizations', [text('name', 'Nombre del club')], {}, 'post', 'org')"><i aria-hidden="true" class="pi pi-plus" /> Crear club</button></div><template v-if="club.selected"><div v-if="club.selected.organization.isDemo" class="demo-banner">DEMO · Este club y todos sus datos iniciales son ficticios.</div><div class="club-summary"><div class="club-crest"><i aria-hidden="true" class="pi pi-shield" /></div><div><span class="eyebrow">TU ORGANIZACIÓN</span><h2>{{ club.selected.organization.name }}</h2><span class="role-tag">{{ club.selected.role.key }}</span></div><div class="club-count"><strong>{{ players.length }}</strong><span>jugadores</span></div><div class="club-count"><strong>{{ teams.length }}</strong><span>equipos</span></div></div><div class="tabs"><button v-for="t in [['players', 'Jugadores'], ['teams', 'Equipos y plantillas'], ['matches', 'Partidos'], ['seasons', 'Temporadas'], ['members', 'Organización']]" :key="t[0]" :class="{ active: tab === t[0] }" @click="tab = t[0]!; detail = undefined">{{ t[1] }}</button></div><div class="section-heading"><form v-if="['players', 'teams'].includes(tab)" class="search" @submit.prevent="load"><i aria-hidden="true" class="pi pi-search" /><input v-model="query" placeholder="Buscar en mi club" aria-label="Buscar en mi club"><button class="icon-button" aria-label="Buscar"><i aria-hidden="true" class="pi pi-arrow-right" /></button></form><h2 v-else>{{ { matches: 'Calendario y resultados', seasons: 'Competiciones y temporadas', members: 'Equipo de trabajo' }[tab] }}</h2><div v-if="club.can('sport:write')" class="action-group"><button v-if="tab === 'players'" class="button primary" @click="player()"><i aria-hidden="true" class="pi pi-plus" /> Jugador</button><template v-if="tab === 'teams'"><button class="button subtle" @click="squad">Asignar plantilla</button><button class="button primary" @click="team()">Nuevo equipo</button></template><button v-if="tab === 'matches'" class="button primary" @click="match">Programar partido</button><template v-if="tab === 'seasons'"><button class="button subtle" @click="open('Nueva competición', '/competitions', [text('name', 'Nombre'), text('country', 'País', 'text', false)])">Competición</button><button class="button primary" @click="open('Nueva temporada', '/competitions/seasons', [select('competitionId', 'Competición', options(competitions)), text('name', 'Nombre'), text('startDate', 'Inicio', 'date'), text('endDate', 'Fin', 'date')])">Temporada</button></template></div><button v-if="tab === 'members' && club.can('members:write')" class="button subtle" @click="invite">Invitar persona</button><button v-if="tab === 'members' && club.can('members:write')" class="button primary" @click="open('Añadir o cambiar rol', `/organizations/${club.selectedId}/members`, [text('email', 'Correo del usuario registrado', 'email'), select('role', 'Rol en este club', roles.filter(r => r !== 'OWNER' || club.selected?.role.key === 'OWNER').map(r => ({ value: r, label: r })))])">Gestionar miembro</button></div><div v-if="message" class="alert success" role="status">{{ message }}</div><StateNotice :loading="busy" :error="error" @retry="load" /><template v-if="!busy && !error"><div v-if="tab === 'players'" class="panel table-scroll"><table><thead><tr><th>Jugador</th><th>Posición</th><th>Nacionalidad</th><th>Acciones</th></tr></thead><tbody><tr v-for="p in players" :key="p.id"><td><RouterLink :to="{ path: `/players/${p.id}`, query: club.params }"><span class="mini-avatar">{{ p.name[0] }}</span>{{ p.name }}</RouterLink></td><td><span class="position">{{ p.position }}</span></td><td>{{ p.nationality ?? '—' }}</td><td><div v-if="club.can('sport:write')" class="action-group"><button class="icon-button" aria-label="Editar jugador" @click="player(p)"><i aria-hidden="true" class="pi pi-pencil" /></button><button class="icon-button" aria-label="Archivar jugador" @click="archive('players', p.id)"><i aria-hidden="true" class="pi pi-inbox" /></button></div></td></tr></tbody></table><StateNotice :empty="!players.length" /></div><div v-if="tab === 'teams'" class="list-grid"><article v-for="t in teams" :key="t.id" class="panel list-item"><i aria-hidden="true" class="pi pi-shield list-icon" /><div><h3>{{ t.name }}</h3><p>{{ t.category }}</p></div><button class="button subtle" @click="showTeam(t.id)">Plantilla</button><template v-if="club.can('sport:write')"><button class="icon-button" aria-label="Editar equipo" @click="team(t)"><i aria-hidden="true" class="pi pi-pencil" /></button><button class="icon-button" aria-label="Archivar equipo" @click="archive('teams', t.id)"><i aria-hidden="true" class="pi pi-inbox" /></button></template></article><StateNotice :empty="!teams.length" /></div><section v-if="detail && tab === 'teams'" class="panel section-gap"><div class="section-heading"><h2>{{ detail.name }}</h2><button v-if="club.can('sport:write')" class="button primary" @click="squad">Añadir a plantilla</button></div><div v-for="s in detail.squads" :key="s.id" class="roster-row"><RouterLink :to="{ path: `/players/${s.playerId}`, query: club.params }">{{ s.player.name }}</RouterLink><span>{{ s.season.name }} · {{ s.shirtNumber ?? 's/d' }} · {{ s.joinedAt.slice(0, 10) }} → {{ s.leftAt?.slice(0, 10) ?? 'actualidad' }}</span></div><div class="section-heading section-gap"><h3>Cuerpo técnico</h3><button v-if="club.can('sport:write')" class="button subtle" @click="open('Añadir técnico', '/teams/staff', [select('teamId', 'Equipo', options(teams)), text('name', 'Nombre'), text('job', 'Función')], { teamId: detail.id })">Añadir</button></div><div v-for="s in detail.staff" :key="s.id" class="roster-row">{{ s.name }}<span>{{ s.job }}</span><button v-if="club.can('sport:write')" class="icon-button" aria-label="Eliminar técnico" @click="removeStaff(s.id)"><i aria-hidden="true" class="pi pi-times" /></button></div></section><div v-if="tab === 'matches'" class="match-list"><MatchCard v-for="m in matches" :key="m.id" :match="m" :organization-id="club.selectedId" /><StateNotice :empty="!matches.length" /></div><div v-if="tab === 'seasons'" class="list-grid"><article v-for="s in seasons" :key="s.id" class="panel list-item"><i aria-hidden="true" class="pi pi-trophy list-icon" /><div><h3>{{ s.name }}</h3><p>{{ s.competition.name }}</p><small class="muted">{{ s.startDate.slice(0, 10) }} — {{ s.endDate.slice(0, 10) }}</small></div></article><StateNotice :empty="!seasons.length" /></div><section v-if="tab === 'members'" class="panel"><button v-if="club.can('club:write')" class="button subtle" @click="open('Editar club', `/organizations/${club.selectedId}`, [text('name', 'Nombre')], { name: club.selected.organization.name }, 'patch')">Editar nombre del club</button><div v-for="m in members" :key="m.id" class="roster-row"><div><strong>{{ m.user.name }}</strong><p class="muted">{{ m.user.email }}</p></div><span class="role-tag">{{ m.role.key }}</span><button v-if="club.can('members:write')" class="button subtle" :aria-label="`Retirar a ${m.user.name}`" @click="removeMember(m.user.id)">Retirar acceso</button></div><div v-if="newInvitation" class="alert success"><strong>Invitación para {{ newInvitation.email }}</strong><p>Comparte este código con esa persona. Debe iniciar sesión con ese correo y elegir Unirme a un equipo. Caduca en 7 días y se usa una sola vez.</p><label>Código para compartir<input :value="newInvitation.token" readonly autocomplete="off" spellcheck="false" @focus="($event.target as HTMLInputElement).select()"></label></div><template v-if="club.can('members:write')"><h3 class="section-gap">Invitaciones pendientes</h3><div v-for="i in invitations" :key="i.id" class="roster-row"><div><strong>{{ i.email }}</strong><p class="muted">{{ i.role }} · Hasta {{ new Date(i.expiresAt).toLocaleDateString('es') }}</p></div><button class="button subtle" @click="revokeInvitation(i.id)">Revocar invitación</button></div><p v-if="!invitations.length" class="muted">No hay invitaciones pendientes.</p></template><p class="chart-footnote">Cada usuario tiene un rol independiente en cada organización.</p></section></template></template><div v-else class="panel state"><i aria-hidden="true" class="pi pi-shield" /><h2>Todo empieza con un equipo.</h2><p>Crea tu club o pide a un propietario que añada tu correo registrado.</p></div><RecordEditor :visible="!!editor" :title="editor?.title ?? ''" :fields="editor?.fields ?? []" :initial="editor?.initial" :busy="saving" :error="editorError" @close="editor = undefined" @save="save" /></section></template>
